},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Mr. Sunflower says: Do you have any small gold stars? Preferably in a sticker format.",
["timestamp"] = 1770071916,
["id"] = "s0_1003",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
