},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Mr. Sunflower says: Oh yes please! Can I get them with writing on it?",
["timestamp"] = 1770071927,
["id"] = "s0_1004",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
