},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Leona Darkstrider says: I am prepared to meet the challenges that lie before me.",
["id"] = "s0_1018",
["timestamp"] = 1771505482,
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
