},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Allari the Souleater says: Show me the precision of your attacks. If you can't focus your hatred, then the demon within you has already won.",
["id"] = "s0_1019",
["timestamp"] = 1771505620,
},
{
