["text"] = "|Hplayer:Kvotheen-Hyjal|h[|cff0070ddKvotheen|r]|h has earned the achievement |cffffff00|Hachievement:61916:Player-1390-09230B89:1:2:19:26:4294967295:4294967295:4294967295:4294967295|h[Rage of the Ren'dorei]|h|r!",
