},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Prattling Pugilist",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Prattling Pugilist says: Did you hear the Brawl'gar Arena is back in business?",
["timestamp"] = 1771526115,
["id"] = "s0_1138",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: Over here, Kvotheen. I've tracked the cultists' activity to the caves below.",
["timestamp"] = 1771526119,
["id"] = "s0_1139",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: We must root out these cultists before they spread their corruption. Find and eliminate them.",
["timestamp"] = 1771526190,
["id"] = "s0_1140",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Suspicious Citizen",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Suspicious Citizen says: What is a Twilight's Blade? Nevermind. I have other places to be.",
["timestamp"] = 1771526213,
["id"] = "s0_1141",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Suspicious Citizen",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Suspicious Citizen says: Bah. Your investigation ends here!",
["timestamp"] = 1771526222,
["id"] = "s0_1142",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Interested Citizen",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Interested Citizen says: I don't want a fight! I'll go!",
["timestamp"] = 1771526224,
["id"] = "s0_1143",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Interested Citizen",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Interested Citizen says: They sounded so compelling, but I'm not interested in cults.",
["timestamp"] = 1771526224,
["id"] = "s0_1144",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Interested Citizen",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Interested Citizen says: Twilight's Blade? Is that what they've been rambling on about? Ridiculous.",
["timestamp"] = 1771526224,
["id"] = "s0_1145",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Greeb Ramrocket",
},
["event"] = "CHAT_MSG_MONSTER_YELL",
["type"] = "MONSTER_YELL",
},
["color"] = {
["r"] = 1,
["g"] = 0.250980406999588,
["b"] = 0.250980406999588,
},
["text"] = "Greeb Ramrocket yells: The zeppelin to Warsong Hold has just arrived! All aboard for Borean Tundra!",
["timestamp"] = 1771526229,
["id"] = "s0_1146",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["event"] = "CHAT_MSG_MONEY",
["type"] = "MONEY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0,
},
["text"] = "You loot 95 Silver, 81 Copper (+1 Silver, 91 Copper)",
["timestamp"] = 1771526234,
["id"] = "s0_1147",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Suspicious Citizen",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Suspicious Citizen says: You know so little. Let me clear things up for you!",
["timestamp"] = 1771526241,
["id"] = "s0_1148",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Interested Citizen",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Interested Citizen says: I'll just go somewhere that's not here for a while.",
["timestamp"] = 1771526243,
["id"] = "s0_1149",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Interested Citizen",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Interested Citizen says: They sounded so compelling, but I'm not interested in cults.",
["timestamp"] = 1771526243,
["id"] = "s0_1150",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["event"] = "CHAT_MSG_MONEY",
["type"] = "MONEY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0,
},
["text"] = "You loot 47 Silver, 36 Copper (+94 Copper)",
["timestamp"] = 1771526247,
["id"] = "s0_1151",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Suspicious Citizen",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Suspicious Citizen says: The Twilight's Blade embraces the end. Join us!",
["timestamp"] = 1771526251,
["id"] = "s0_1152",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Interested Citizen",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Interested Citizen says: Leave me out of this!",
["timestamp"] = 1771526253,
["id"] = "s0_1153",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Interested Citizen",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Interested Citizen says: I don't want a fight! I'll go!",
["timestamp"] = 1771526253,
["id"] = "s0_1154",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["event"] = "CHAT_MSG_MONEY",
["type"] = "MONEY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0,
},
["text"] = "You loot 1 Gold, 12 Silver, 11 Copper (+2 Silver, 23 Copper)",
["timestamp"] = 1771526256,
["id"] = "s0_1155",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Garrulous Gladiator",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Garrulous Gladiator says: Come now. Where's your ambition?",
["timestamp"] = 1771526259,
["id"] = "s0_1156",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: So the Twilight's Blade are indeed recruiting here. I suppose I have to work with Umbric after all.",
["timestamp"] = 1771526267,
["id"] = "s0_1157",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: It's imperative that we stop the Twilight's Blade at its source: The Twilight Highlands.",
["timestamp"] = 1771526293,
["id"] = "s0_1158",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: This portal will take you to our base of operations. I'll meet you there.",
["timestamp"] = 1771526299,
["id"] = "s0_1159",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: Yet more minds twisted by the Void. This must seem quite familiar to you, Umbric.",
["timestamp"] = 1771526304,
["id"] = "s0_1160",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Ray of Putrescence",
},
["event"] = "CHAT_MSG_MONSTER_EMOTE",
["type"] = "MONSTER_EMOTE",
},
["color"] = {
["r"] = 1,
["g"] = 0.501960813999176,
["b"] = 0.250980406999588,
},
["text"] = "Ray of Putrescence's ritual has been interrupted! Finish it!",
["timestamp"] = 1771526311,
["id"] = "s0_1161",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: Infiltrate the cult and see what you can learn. But do not succumb to the allure of their sermons.",
["timestamp"] = 1771526324,
["id"] = "s0_1162",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Magister Umbric",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Magister Umbric says: A strong enough will can resist the call of Void, Rommath. You would do well to remember that.",
["timestamp"] = 1771526331,
["id"] = "s0_1163",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: We may have removed the cult's presence from Orgrimmar and Stormwind, but their numbers still grow. This is a staging ground.",
["timestamp"] = 1771526335,
["id"] = "s0_1164",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Magister Umbric",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Magister Umbric says: Arator told me of a larger force being assembled by Xal'atath. The Twilight's Blade seems a lesser threat by comparison.",
["timestamp"] = 1771526343,
["id"] = "s0_1165",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: Every practitioner of void magic is a threat, Umbric. Have your own mistakes and misadventures done nothing to teach you that?",
["timestamp"] = 1771526353,
["id"] = "s0_1166",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Magister Umbric",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Magister Umbric says: Becoming ren'dorei has proven to me the opposite. The Void can be harnessed for good, and its wielders left in control of their minds.",
["timestamp"] = 1771526361,
["id"] = "s0_1167",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Magister Umbric",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Magister Umbric says: If you want to speak of \"mistakes,\" look to your own Magisters. How many times has their pursuit of power nearly led to ruin?",
["timestamp"] = 1771526372,
["id"] = "s0_1168",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: I will not be lectured by you! Not when you forced me to exile you from Silvermoon for refusing to abandon your forbidden research!",
["timestamp"] = 1771526380,
["id"] = "s0_1169",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Magister Umbric",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Magister Umbric says: The knowledge gleaned from that research has saved our world countless times! You're merely too stubborn to acknowledge it!",
["timestamp"] = 1771526389,
["id"] = "s0_1170",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Grand Magister Rommath",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Grand Magister Rommath says: Enough! Like everything else you do, this plan to infiltrate the cult is foolhardy and dangerous. It had better work, Umbric.",
["timestamp"] = 1771526400,
["id"] = "s0_1171",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Magister Umbric",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Magister Umbric says: Oh it will, Rommath. The question is whether or not you'll admit it when it does.",
["timestamp"] = 1771526407,
["id"] = "s0_1172",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Ix the Bloodfallen",
},
["event"] = "CHAT_MSG_MONSTER_EMOTE",
["type"] = "MONSTER_EMOTE",
},
["color"] = {
["r"] = 1,
["g"] = 0.501960813999176,
["b"] = 0.250980406999588,
},
["text"] = "The Twilight's Blade have begun summoning more forces. Defeat their ritual leaders!",
["timestamp"] = 1771526472,
["id"] = "s0_1173",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["event"] = "CHAT_MSG_MONEY",
["type"] = "MONEY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0,
},
