},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Gehl Harrowtongue says: You. Acolyte. Haven't you finished your training? Where is your tabard?",
["timestamp"] = 1771526677,
["id"] = "s0_1182",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Gehl Harrowtongue",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Gehl Harrowtongue says: Prove yourself as one Xal'atath's faithful. Only then may you attend the initiation ceremony.",
["timestamp"] = 1771526704,
["id"] = "s0_1183",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Studious Voidcaster",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Studious Voidcaster says: With this fight, I'll prove myself to Xal'atath!",
["timestamp"] = 1771526731,
["id"] = "s0_1184",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
