["id"] = "s0_1192",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Gehl Harrowtongue",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Gehl Harrowtongue says: You appear to be ready for your initiation now, fledgling. This way.",
["timestamp"] = 1771526792,
["id"] = "s0_1193",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Gehl Harrowtongue",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Gehl Harrowtongue says: Take heed of Mor'duun's speech. Our leader's words have set many cultists' hearts afire. I'm sure they will yours as well.",
["timestamp"] = 1771526808,
["id"] = "s0_1194",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Projection of Mor'duun",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Projection of Mor'duun says: We are the Twilight's Blade. The void-black dagger Xal'atath wields against Azeroth.",
