},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Projection of Mor'duun",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Projection of Mor'duun says: We cut deep. Blood. Carnage. Chaos! This is what gains her favor. This is our glorious purpose!",
["timestamp"] = 1771526848,
["id"] = "s0_1198",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Projection of Mor'duun",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Projection of Mor'duun says: We shall strike at the heart of Azeroth and end this flawed world. For Xal'atath! For the Twilight's Blade!",
["timestamp"] = 1771526855,
["id"] = "s0_1199",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Magister Umbric",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Magister Umbric says: Excellent work, Kvotheen. I believe we have learned enough here. Time to tear this camp apart.",
["timestamp"] = 1771526871,
["id"] = "s0_1200",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
