},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Magister Umbric says: I will meet you back at the basecamp. Our fight against this cult is only beginning.",
["timestamp"] = 1771526896,
["id"] = "s0_1201",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Gehl Harrowtongue",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Gehl Harrowtongue says: You still haven't learned. The Twilight's Blade will be your end!",
["timestamp"] = 1771526906,
["id"] = "s0_1202",
},
{
